    "question": "Quanto à Declaração Universal dos Direitos \nHumanos de 1948, analise as assertivas e assinale \na alternativa que aponta as corretas. \n\nI. Todas as pessoas nascem livres e iguais em \ndignidade e direitos. São dotadas de razão e \nconsciência e devem agir em relação umas às \noutras com espírito de fraternidade. \n\nII. Toda pessoa tem capacidade para gozar os \ndireitos e as liberdades estabelecidos nesta \nDeclaração, sem distinção d e qualquer espécie, \nseja de raça, cor, sexo, língua, religião, opinião \npolítica ou de outra natureza, origem nacional ou \nsocial, riqueza, nascimento, ou qualquer outra \ncondição. \n\nIII. Toda pessoa tem direito à vida, à liberdade e à \nsegurança pessoal. \n\nIV. Ninguém será mantido em escravidão ou \nservidão, a escravidão e o tráfico de escravos serão \nproibidos em todas as suas formas.",
