    "question": "O re speito à integridade física do preso é uma \npreocupação de diversos documentos jurídicos \nnacionais e internacionais, destacando, por \nexemplo, “As Regras Mínimas da ONU para o \ntratamento de pessoas presas” e o “Programa \nNacional de Direitos Humanos” (Decreto nº \n7.037/09). Tendo por base esses documentos \njurídicos, o Código Penal e o disposto na Lei nº \n9.455/97, imagine a seguinte situação hipotética: \n\nDurante procedimento de rotina realizado em um \ndos presídios do Estado de Roraima, os agentes \npenitenciários José e Paulo flagraram o detento \nJoão sendo agredido pelo seu companheiro de cela \nde nome Afonso. Diante da situação, os agentes \npenitenciários foram em direção aos detentos e \nconseguiram imobilizar Afonso, salvando João, que \nestava gravemente ferido e foi encaminhado para a \nala médica. Inconformados com a atitude de \nAfonso, a fim de castigá -lo, José e Paulo levaram o \ndetento para uma das salas do estabelecimento \nprisional. Em seguida, enquanto José vigiava o \nambiente para evitar a aproximação de outros \nservidores, Paulo agrediu Afonso com diversos socos e \nchutes, causando-lhe intenso sofrimento físico. Quando \nse sentiram satisfeitos com o castigo pessoal aplicado, \nos agentes penitenciários levaram Afonso para o setor \nhospitalar do estabelecimento prisional . Diante dessa \nsituação hipotética, no tocante à aplicação do direito \npenal, é correto afirmar que",
